from z3 import *

def solve_sgp(n_golfers, n_groups, n_players_per_group, n_weeks):
    # n_golfers = 30
    # n_groups = 10
    # n_players_per_group = 3
    # n_weeks = 8

    # Variables: x[w][p] is the group of golfer p in week w
    x = [[Int(f"x_{w}_{p}") for p in range(n_golfers)] for w in range(n_weeks)]

    solver = Solver()

    # Constraints:
    # 1. Each golfer is in exactly one group per week (0 to n_groups-1)
    for w in range(n_weeks):
        for p in range(n_golfers):
            solver.add(x[w][p] >= 0, x[w][p] < n_groups)

    # 2. Each group has exactly n_players_per_group golfers
    for w in range(n_weeks):
        for g in range(n_groups):
            solver.add(Sum([If(x[w][p] == g, 1, 0) for p in range(n_golfers)]) == n_players_per_group)

    # 3. No pair of golfers in the same group more than once
    # For every pair of golfers (p1, p2), they can be in the same group at most once
    for p1 in range(n_golfers):
        for p2 in range(p1 + 1, n_golfers):
            solver.add(Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(n_weeks)]) <= 1)

    if solver.check() == sat:
        model = solver.model()
        result = []
        for w in range(n_weeks):
            for p in range(n_golfers):
                result.append(model.evaluate(x[w][p]).as_long())
        return result
    else:
        return None

