def verify_solution(n_golfers, n_groups, n_players_per_group, n_weeks, solution):
    if len(solution) != n_golfers * n_weeks:
        return False, "Incorrect length"

    # Check each week
    for w in range(n_weeks):
        week_groups = [[] for _ in range(n_groups)]
        for p in range(n_golfers):
            group = solution[w * n_golfers + p]
            if group < 0 or group >= n_groups:
                return False, f"Invalid group {group} for golfer {p} in week {w}"
            week_groups[group].append(p)

        for g in range(n_groups):
            if len(week_groups[g]) != n_players_per_group:
                return False, f"Group {g} in week {w} has {len(week_groups[g])} players, expected {n_players_per_group}"

    # Check pairs
    pairs = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            group_players = [p for p in range(n_golfers) if solution[w * n_golfers + p] == g]
            for i in range(len(group_players)):
                for j in range(i + 1, len(group_players)):
                    p1, p2 = group_players[i], group_players[j]
                    pair = tuple(sorted((p1, p2)))
                    if pair in pairs:
                        return False, f"Pair {pair} met in week {pairs[pair]} and week {w}"
                    pairs[pair] = w

    return True, "Valid"

